CREATE TABLE webhook_endpoints(id BINARY(16) PRIMARY KEY,tenant_id BINARY(16) NOT NULL,url VARCHAR(2048) NOT NULL,encrypted_secret TEXT NOT NULL,event_subscriptions_json TEXT NOT NULL,environment VARCHAR(100) NOT NULL,active BOOLEAN NOT NULL,timeout_ms INT NOT NULL,max_retries INT NOT NULL,revision BIGINT NOT NULL);
CREATE TABLE webhook_deliveries(id BINARY(16) PRIMARY KEY,endpoint_id BINARY(16) NOT NULL,event_id VARCHAR(255) NOT NULL,event_type VARCHAR(255) NOT NULL,payload TEXT NOT NULL,status VARCHAR(30) NOT NULL,attempt_count INT NOT NULL,next_attempt_at TIMESTAMP(6) NOT NULL,last_http_status INT,last_error VARCHAR(1000),created_at TIMESTAMP(6) NOT NULL,delivered_at TIMESTAMP(6),revision BIGINT NOT NULL,UNIQUE(endpoint_id,event_id),INDEX idx_delivery_worker(status,next_attempt_at),FOREIGN KEY(endpoint_id) REFERENCES webhook_endpoints(id));
CREATE TABLE webhook_attempts(id BINARY(16) PRIMARY KEY,delivery_id BINARY(16) NOT NULL,attempt_number INT NOT NULL,http_status INT,error VARCHAR(1000),attempted_at TIMESTAMP(6) NOT NULL,FOREIGN KEY(delivery_id) REFERENCES webhook_deliveries(id) ON DELETE CASCADE);